240:             "registry_name": {"type": ["string", "null"],
241:               "description": "model: 该依赖的规范/注册表包名（PyPI/npm/Maven artifact/crate；或 CMake find_package 的真实包名），当 `name` 是别名/接口名/缩写时填它，便于按名关联到已分析库。不确定则 null。"},
242:             "source_repo": {"type": ["string", "null"],
243:               "description": "model (best-effort): 该依赖的上游源码仓库 URL（github/gitlab/gitee/自托管均可）。是把依赖关联到已分析库的最强键——能从 manifest/lock/已知常识判断就填，含 `find_package(PNG)`→glennrp/libpng 这类名≠仓的情形。不确定则 null。"},
244:             "import_names": {"type": "array", "items": {"type": "string"},
245:               "description": "model: 实际 import 名（如依赖 Pillow → 代码里 import PIL）。无则省略。"},
246:             "aliases": {"type": "array", "items": {"type": "string"},
247:               "description": "model: 该依赖的其它已知名称/拼写。无则省略。"},
248:             "scope": {"type": "string", "description": "runtime/dev/test/optional/build"},
249:             "version": {"type": ["string", "null"]},
250:             "purpose": {"type": "string", "description": "model: why it's used"},
251:             "acquisition": {"type": "string",
252:               "description": "OPEN vocabulary — how the build OBTAINS this dependency. Recommended values: system (find_package/expected pre-installed), vendored (source copied into the tree), fetchcontent (CMake FetchContent), download_build (ExternalProject/custom download-source-and-build), submodule (git submodule), package_manager (vcpkg/conan/pip/npm/maven), prebuilt_binary (binary shipped in repo). If none fits, coin a concise lowercase token (e.g. conda, apt, cpm, git_subtree, runtime_download) AND record it in meta.observations. Also set the closed `locality` field accordingly."},
253:             "locality": {"type": "string",
254:               "enum": ["local", "remote", "system", "runtime", "unknown"],
255:               "description": "STABLE axis (model-set): local=already in repo (vendored/prebuilt); remote=pulled from outside (fetchcontent/download/submodule/registry); system=expected pre-installed via find_package; runtime=loaded at runtime; unknown"},
256:             "source": {"type": "string", "description": "model: WHERE it is obtained from — download URL / registry / 'system (find_package, must be pre-installed)' / in-tree path, 简体中文"},
257:             "declared_in": {"type": "array", "items": {"type": "string"},
258:               "description": "model: repo file(s) that declare how this dependency is integrated, e.g. the CMakeLists.txt with find_package/FetchContent_Declare/ExternalProject_Add/target_link_libraries, a .gitmodules entry, or a requirements/manifest line"},
259:             "used_symbols": {"type": "array", "items": {"type": "string"},
260:               "description": "model (best-effort, codegraph/grep): the dependency's public symbols / APIs THIS library actually calls (e.g. cairo_create, BIO_new, numpy.ndarray). Consumed by dim-9 bottom-up rollup: a child's un-adaptable API only blocks this (parent) library if it appears here. Omit/empty for system deps or when usage can't be pinned down (rollup then falls back to dependency scope)."},
261:             "harmony_adapted": {"type": "boolean", "description": "SCRIPT-stamped (scripts/harmony_adapted.js): true if this package already has an official HarmonyOS PC build in the OpenHarmony PC mirror (an *-ohos_*.whl etc.). Consumed by dim 9 (already-adapted dep ⇒ not a blocker). Do NOT set by hand."},
262:             "harmony_adapted_source": {"type": ["string", "null"], "description": "SCRIPT-stamped: which OpenHarmony PC mirror provides the adapted build."}}}},
263:         "notes": {"type": "string"}
